window.VO = [{"id":"n01","text":"You're the cashier, and he's got a knife.","at":0.24,"t0":0.12,"t1":2.095},{"id":"r01","text":"Open the drawer!","at":4.69,"t0":2.345,"t1":3.445},{"id":"n02","text":"Now pick him.","at":9.89,"t0":4.945,"t1":5.815},{"id":"n03","text":"Whoever you pick goes to jail.","at":12.03,"t0":6.015,"t1":7.66},{"id":"n04","text":"Now pick his knife.","at":20.92,"t0":10.46,"t1":11.62},{"id":"n05","text":"You'd know that knife anywhere.","at":27.24,"t0":13.62,"t1":15.025},{"id":"n06","text":"But the knife doesn't go to jail.","at":30.75,"t0":15.375,"t1":16.965},{"id":"n07","text":"Were you that sure of the man you sent to jail?","at":35.13,"t0":17.565,"t1":19.71},{"id":"n08","text":"His face was right there.","at":40.42,"t0":20.21,"t1":21.645},{"id":"n09","text":"He's number two.","at":44.29,"t0":22.145,"t1":23.205},{"id":"n10","text":"Picked nobody? He's still out there.","at":47.41,"t0":23.705,"t1":25.64},{"id":"n11","text":"Picked one, three or four?","at":52.28,"t0":26.14,"t1":27.57},{"id":"n12","text":"You just sent an innocent man to jail.","at":57.34,"t0":28.67,"t1":30.575},{"id":"n13","text":"It's called weapon focus.","at":63.15,"t0":31.575,"t1":33.1},{"id":"n14","text":"In the classic test, one in three chose the right man.","at":66.8,"t0":33.4,"t1":36.475},{"id":"n14b","text":"With a gun, one in seven.","at":73.55,"t0":36.775,"t1":38.405},{"id":"n15","text":"Got number two?","at":78.41,"t0":39.205,"t1":40.265},{"id":"n16","text":"Then who else was in the shop?","at":81.33,"t0":40.665,"t1":42.12}];
